:root {
  --bg: #1e1e2e;
  --card: #2a2a3c;
  --text: #e0e0f0;
  --accent: #7aa2f7;
  --hunger: #f7768e;
  --happiness: #e0af68;
  --energy: #9ece6a;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: var(--radius);
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  font-size: 1.75rem;
  text-align: center;
  color: var(--accent);
  letter-spacing: 1px;
}

.pet-area {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.pet {
  width: 96px;
  height: 96px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.2s ease;
}

.pet-body {
  position: relative;
  width: 80px;
  height: 80px;
  background: var(--accent);
  border-radius: 16px;
  image-rendering: pixelated;
  box-shadow: 0 4px 0 rgba(0, 0, 0, 0.3);
}

.pet-eye {
  position: absolute;
  top: 24px;
  width: 12px;
  height: 12px;
  background: #1e1e2e;
  border-radius: 2px;
}

.pet-eye.left { left: 18px; }
.pet-eye.right { right: 18px; }

.pet-mouth {
  position: absolute;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  width: 24px;
  height: 8px;
  background: #1e1e2e;
  border-radius: 0 0 8px 8px;
}

.pet.sleeping .pet-eye {
  height: 2px;
  top: 29px;
}

.pet.sleeping .pet-mouth {
  width: 12px;
  height: 4px;
  border-radius: 4px 4px 0 0;
}

.mood {
  font-size: 1.1rem;
  text-align: center;
  min-height: 1.5em;
  color: var(--accent);
  font-weight: 600;
}

.stats {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.stat-label {
  font-size: 0.95rem;
  font-weight: 600;
  opacity: 0.9;
}

.bar {
  height: 20px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  overflow: hidden;
}

.fill {
  height: 100%;
  width: 100%;
  border-radius: 10px;
  transition: width 0.4s ease;
}

.fill.hunger { background: var(--hunger); }
.fill.happiness { background: var(--happiness); }
.fill.energy { background: var(--energy); }

.controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
}

button {
  flex: 1 1 0;
  min-width: 90px;
  padding: 12px 16px;
  font-size: 1rem;
  font-family: var(--font);
  font-weight: 600;
  color: var(--bg);
  background: var(--accent);
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.2s ease, transform 0.1s ease, box-shadow 0.2s ease;
}

button:hover {
  background: #9bb8ff;
}

button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.96);
  background: #5c7dd9;
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

@media (max-width: 360px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  button {
    min-width: 70px;
    padding: 10px 8px;
    font-size: 0.9rem;
  }
}

const state = { hunger: 100, happiness: 100, energy: 100 };

const moodEl = document.getElementById('mood');
const petEl = document.getElementById('pet');
const bars = {
  hunger: document.getElementById('hunger-bar'),
  happiness: document.getElementById('happiness-bar'),
  energy: document.getElementById('energy-bar')
};
const fills = {
  hunger: document.getElementById('hunger-fill'),
  happiness: document.getElementById('happiness-fill'),
  energy: document.getElementById('energy-fill')
};

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

function updateUI() {
  for (const key of Object.keys(state)) {
    const value = state[key];
    fills[key].style.width = value + '%';
    bars[key].setAttribute('aria-valuenow', value);
  }

  const avg = (state.hunger + state.happiness + state.energy) / 3;
  let mood = '';
  let sleeping = false;

  if (avg >= 80) mood = 'Your pet is thriving!';
  else if (avg >= 50) mood = 'Your pet is content.';
  else if (avg >= 25) mood = 'Your pet needs some care.';
  else mood = 'Your pet is not doing well...';

  if (state.energy < 20) {
    mood = 'Your pet is exhausted. Let it sleep.';
    sleeping = true;
  }

  petEl.classList.toggle('sleeping', sleeping);
  moodEl.textContent = mood;
}

function feed() {
  state.hunger = clamp(state.hunger + 20);
  state.happiness = clamp(state.happiness + 5);
  state.energy = clamp(state.energy - 5);
  updateUI();
}

function play() {
  state.happiness = clamp(state.happiness + 20);
  state.hunger = clamp(state.hunger - 10);
  state.energy = clamp(state.energy - 15);
  updateUI();
}

function sleep() {
  state.energy = clamp(state.energy + 30);
  state.hunger = clamp(state.hunger - 10);
  state.happiness = clamp(state.happiness - 5);
  updateUI();
}

document.getElementById('feed-btn').addEventListener('click', feed);
document.getElementById('play-btn').addEventListener('click', play);
document.getElementById('sleep-btn').addEventListener('click', sleep);

updateUI();
